import{_ as t,y as r,a as s,o as n,ag as i,D as o}from"./chunks/framework.C2qfZH9T.js";const h=JSON.parse('{"title":"Commerce électronique multi-locataires","description":"","frontmatter":{},"headers":[],"relativePath":"multi-tenant-ecommerce/introduction.md","filePath":"multi-tenant-ecommerce/introduction.md","lastUpdated":1782937842000}'),l={name:"multi-tenant-ecommerce/introduction.md"};function u(c,e,m,p,d,g){const a=r("ImagePopup");return n(),s("div",null,[e[0]||(e[0]=i('<h1 id="commerce-electronique-multi-locataires" tabindex="-1">Commerce électronique multi-locataires <a class="header-anchor" href="#commerce-electronique-multi-locataires" aria-label="Permalink to &quot;Commerce électronique multi-locataires&quot;">​</a></h1><p><a href="https://www.exaland.app/ecommercelaravel-multi-tenant-saas/" target="_blank" rel="noreferrer">Commerce électronique multi-tenant</a> dans ExalandStore permet aux entreprises de créer une plate-forme de marché basée sur SaaS où plusieurs fournisseurs ou commerçants peuvent créer et gérer leurs propres magasins individuels sous un seul système.</p><p>Chaque locataire (commerçant) dispose d&#39;une vitrine dédiée avec un contrôle total sur les produits, les catégories, les commandes et les clients, tandis que le propriétaire de la plateforme gère l&#39;infrastructure globale, les abonnements et les modèles de revenus. Cette configuration réduit les coûts opérationnels pour les commerçants, car ils n&#39;ont pas besoin d&#39;investir dans un développement ou un hébergement de commerce électronique distinct.</p><h3 id="gestion-des-super-administrateurs" tabindex="-1">Gestion des super-administrateurs <a class="header-anchor" href="#gestion-des-super-administrateurs" aria-label="Permalink to &quot;Gestion des super-administrateurs&quot;">​</a></h3><p>Le poste de super administrateur est la principale autorité du centre commercial SaaS, chargé de superviser les locataires, le personnel et l&#39;ensemble des opérations de la plateforme.</p><p>Ce rôle consiste à gérer les commerçants (locataires), à attribuer des rôles au personnel (agents) et à s&#39;assurer que tout fonctionne bien dans le système.</p><p>Les super administrateurs définissent les produits visibles, gèrent les canaux et conçoivent des thèmes pour conserver une apparence et une image de marque cohérentes pour tous les magasins locataires.</p><p>Ils s&#39;occupent également des pages CMS, envoient des diffusions par e-mail et gèrent les paramètres globaux pour garantir une communication claire et une bonne gouvernance de la plateforme.</p><h3 id="gestion-des-locataires" tabindex="-1">Gestion des locataires <a class="header-anchor" href="#gestion-des-locataires" aria-label="Permalink to &quot;Gestion des locataires&quot;">​</a></h3><p>La gestion des locataires dans le SaaS permet aux locataires de s&#39;inscrire facilement et de créer rapidement leur boutique en ligne en remplissant leurs informations de connexion, personnelles et organisationnelles.</p><p>Après son inscription, la vitrine du locataire est automatiquement configurée, ce qui lui permet de commencer à vendre immédiatement sans aucune difficulté technique.</p><p>À l&#39;aide du panneau d&#39;administration des locataires, les locataires peuvent gérer les produits, les catégories, les attributs, les clients et bien plus encore via une interface conviviale similaire à ExalandStore.</p><p>Les locataires peuvent également gérer les commandes en établissant des factures, en organisant les expéditions et en utilisant d&#39;autres options de menu pour gérer efficacement leur magasin.</p><h3 id="mappage-de-noms-c" tabindex="-1">Mappage de noms C <a class="header-anchor" href="#mappage-de-noms-c" aria-label="Permalink to &quot;Mappage de noms C&quot;">​</a></h3><p>CName Mapping permet aux locataires de connecter leur propre domaine au sous-domaine créé par le SaaS, ce qui contribue à l&#39;image de marque professionnelle.</p><p>Lorsqu&#39;un locataire s&#39;inscrit, un sous-domaine par défaut tel que <strong>username.rootdomain.com</strong> est créé. Avec CNAME, leur domaine réel peut être dirigé vers ce sous-domaine.</p><p>Cela permet aux clients de trouver facilement le magasin et de conserver une image en ligne fiable et cohérente.</p><p>Le mappage est configuré via le fournisseur DNS du locataire et le SaaS par le super administrateur, et il ne nécessite aucun plugin supplémentaire.</p>',18)),o(a,{src:"/images/multi-tenant-ecommerce/multi-tenant.webp",alt:"Super Admin Login"})])}const v=t(l,[["render",u]]);export{h as __pageData,v as default};
